const fs = require('fs');
const content = fs.readFileSync('assets/functions/snakeGame/snakeGame.js', 'utf8');

const matchUp = content.match(/headUp:\s*\[([\s\S]*?)\]\s*,\s*headDown/);
if (!matchUp) {
  console.log('Could not match headUp');
  process.exit(1);
}

const headUpLines = matchUp[1].trim().split('\n').map(l => l.trim().replace(/^["']|["'],?$/g, ''));
console.log('headUp lines:', headUpLines.length, 'width:', headUpLines[0].length);

// Rotate 90 degrees clockwise (for headRight)
const N = headUpLines.length;
const rotatedCW = [];
for (let r = 0; r < N; r++) {
  let rowStr = '';
  for (let c = 0; c < N; c++) {
    rowStr += headUpLines[N - 1 - c][r];
  }
  rotatedCW.push(rowStr);
}

console.log('Rotated CW 90 (headRight candidates):');
rotatedCW.slice(0, 5).forEach((r, i) => console.log(i + 1, r));

// Also check current headRight in file
const matchRight = content.match(/headRight:\s*\[([\s\S]*?)\]\s*,\s*headLeft/);
if (matchRight) {
  const headRightLines = matchRight[1].trim().split('\n').map(l => l.trim().replace(/^["']|["'],?$/g, ''));
  console.log('Current headRight lines:', headRightLines.length);
}
