arguments.command:
@'
const fs = require('fs');
const content = fs.readFileSync('assets/functions/snakeGame/snakeGame.js', 'utf8');

// Parse headUp and headRight from the file
const getSprite = (name) => {
  const regex = new RegExp(name + ':\\s*\\[([\\s\\S]*?)\\]\\s*(,|})');
  const m = content.match(regex);
  if (!m) return null;
  return m[1].trim().split('\n').map(l => {
    const q = l.match(/["'](.*?)["']/);
    return q ? q[1] : '';
  });
};

const headUp = getSprite('headUp');
const headRight = getSprite('headRight');

console.log('headUp rows:', headUp.length, 'cols:', headUp[0].length);
console.log('headRight rows:', headRight.length, 'cols:', headRight[0].length);

// Rotate headUp 90 degrees clockwise
const N = headUp.length;
const rotatedCW = [];
for (let r = 0; r < N; r++) {
  let rowStr = '';
  for (let c = 0; c < N; c++) {
    rowStr += headUp[N - 1 - c][r];
  }
  rotatedCW.push(rowStr);
}

// Compare rotatedCW with headRight
let diffs = 0;
for (let i = 0; i < N; i++) {
  if (rotatedCW[i] !== headRight[i]) {
    diffs++;
    console.log(`Diff at row ${i}:`);
    console.log('CW:   ', rotatedCW[i]);
    console.log('Right:', headRight[i]);
  }
}
console.log('Total diffs between headUp rotated CW 90 and headRight:', diffs);
