const fs = require('fs');
const filePath = 'assets/functions/snakeGame/snakeGame.js';
const content = fs.readFileSync(filePath, 'utf8');

const getSprite = (name) => {
  const m = content.match(new RegExp(name + ':\\s*\\[([\\s\\S]*?)\\]\\s*(,|})'));
  return m ? m[1].trim().split('\n').map(l => { const q = l.match(/["'](.*?)["']/); return q ? q[1] : ''; }) : null;
};

const headUp = getSprite('headUp');
const N = headUp.length;

const rotateCW = (arr) => {
  const res = [];
  for (let r = 0; r < N; r++) {
    let rowStr = '';
    for (let c = 0; c < N; c++) rowStr += arr[N - 1 - c][r];
    res.push('        "' + rowStr + '"');
  }
  return res.join(',\n');
};

const rotateCCW = (arr) => {
  const res = [];
  for (let r = 0; r < N; r++) {
    let rowStr = '';
    for (let c = 0; c < N; c++) rowStr += arr[c][N - 1 - r];
    res.push('        "' + rowStr + '"');
  }
  return res.join(',\n');
};

const newHeadLeft = rotateCCW(headUp);
const newHeadRight = rotateCW(headUp);

// Replace headLeft
let updated = content.replace(
  /headLeft:\s*\[[\s\S]*?\],\s*headRight/,
  `headLeft: [\n${newHeadLeft}\n      ],\n      headRight`
);

// Replace headRight
updated = updated.replace(
  /headRight:\s*\[[\s\S]*?\],\s*body/,
  `headRight: [\n${newHeadRight}\n      ],\n      body`
);

fs.writeFileSync(filePath, updated, 'utf8');
console.log('Successfully updated headLeft and headRight in snakeGame.js');
