const fs = require('fs');
const filePath = 'assets/functions/snakeGame/snakeGame.js';
let content = fs.readFileSync(filePath, 'utf8').replace(/\r\n/g, '\n');

const getSpriteLines = (name) => {
  const regex = new RegExp(name + ':\\s*\\[([\\s\\S]*?)\\]');
  const match = content.match(regex);
  if (!match) return null;
  const lines = match[1].split('\n');
  const result = [];
  for (let l of lines) {
    const q = l.match(/["'](.*?)["']/);
    if (q && q[1].length > 0) {
      let s = q[1];
      while (s.length < 32) s += '.';
      if (s.length > 32) s = s.slice(0, 32);
      result.push(s);
    }
  }
  return result;
};

const headUp = getSpriteLines('headUp');
const N = 32;

const rotateCW = (arr) => {
  const res = [];
  for (let r = 0; r < N; r++) {
    let rowStr = '';
    for (let c = 0; c < N; c++) {
      rowStr += arr[N - 1 - c][r];
    }
    res.push('        "' + rowStr + '"');
  }
  return res.join(',\n');
};

const rotateCCW = (arr) => {
  const res = [];
  for (let r = 0; r < N; r++) {
    let rowStr = '';
    for (let c = 0; c < N; c++) {
      rowStr += arr[c][N - 1 - r];
    }
    res.push('        "' + rowStr + '"');
  }
  return res.join(',\n');
};

const newHeadLeft = rotateCCW(headUp);
const newHeadRight = rotateCW(headUp);

// Replace headLeft block
content = content.replace(
  /headLeft:\s*\[[\s\S]*?\]\s*,/,
  `headLeft: [\n${newHeadLeft}\n      ],`
);

// Replace headRight block
content = content.replace(
  /headRight:\s*\[[\s\S]*?\]\s*,/,
  `headRight: [\n${newHeadRight}\n      ],`
);

content = content.replace(/\n/g, '\r\n');
fs.writeFileSync(filePath, content, 'utf8');
console.log('Successfully updated headLeft and headRight with 32x32 rotation!');
